*** Begin Patch
*** Update File: /Users/lainniay/Code/Cpp/WebServer/root/log_template.html
@@
-      <p>Review the selected server log file with preserved line spacing and rotation metadata.</p>
+      <p>Review merged server logs by date, level, and keyword with preserved line spacing.</p>
@@
     .section p {
       margin-bottom: 18px;
       font-size: 14px;
     }
+
+    .filters {
+      display: grid;
+      gap: 14px;
+      grid-template-columns: repeat(4, minmax(0, 1fr));
+      align-items: end;
+    }
+
+    .field {
+      display: grid;
+      gap: 8px;
+    }
+
+    .field label {
+      color: var(--muted);
+      font-size: 12px;
+      font-weight: 800;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+    }
+
+    .field input,
+    .field select {
+      width: 100%;
+      min-height: 44px;
+      padding: 10px 12px;
+      border: 1px solid var(--line-strong);
+      border-radius: 14px;
+      background: #fbfffc;
+      color: var(--ink);
+      font: inherit;
+      font-weight: 700;
+    }
+
+    .field input:focus,
+    .field select:focus {
+      outline: 3px solid var(--accent-soft);
+      border-color: var(--accent);
+    }
+
+    .filter-button {
+      min-height: 44px;
+      padding: 10px 16px;
+      border: 1px solid var(--accent-dark);
+      border-radius: 14px;
+      background: var(--accent);
+      color: #ffffff;
+      font: inherit;
+      font-weight: 900;
+      cursor: pointer;
+    }
+
+    .filter-button:hover {
+      background: var(--accent-dark);
+    }

     .metadata {
       display: grid;
       gap: 16px;
-      grid-template-columns: repeat(4, minmax(0, 1fr));
+      grid-template-columns: repeat(3, minmax(0, 1fr));
     }
@@
     @media (max-width: 820px) {
+      .filters,
       .metadata {
         grid-template-columns: repeat(2, minmax(0, 1fr));
       }
@@
-      .metadata,
+      .filters,
+      .metadata,
       .actions {
         grid-template-columns: 1fr;
       }
@@
       <section class="section" aria-labelledby="log-metadata-heading">
-        <h2 id="log-metadata-heading">Log Metadata</h2>
-        <p>Status and file details for the selected log snapshot.</p>
+        <h2 id="log-metadata-heading">Merged Log Filters</h2>
+        <p>Filter merged server logs by date directory, severity level, and keyword.</p>
+        <form class="filters" action="/log.html" method="get">
+          <div class="field">
+            <label for="log-date">Date</label>
+            <input id="log-date" name="date" type="date" value="{{log.date}}">
+          </div>
+
+          <div class="field">
+            <label for="log-level">Level</label>
+            <select id="log-level" name="level">
+              <option value="all" {{log.level.all_selected}}>All</option>
+              <option value="debug" {{log.level.debug_selected}}>Debug</option>
+              <option value="info" {{log.level.info_selected}}>Info</option>
+              <option value="warn" {{log.level.warn_selected}}>Warn</option>
+              <option value="error" {{log.level.error_selected}}>Error</option>
+            </select>
+          </div>
+
+          <div class="field">
+            <label for="log-keyword">Keyword</label>
+            <input id="log-keyword" name="keyword" type="search" value="{{log.keyword}}" placeholder="Search merged logs">
+          </div>
+
+          <button class="filter-button" type="submit">Apply Filters</button>
+        </form>
+      </section>
+
+      <section class="section" aria-labelledby="log-metadata-summary-heading">
+        <h2 id="log-metadata-summary-heading">Merged Log Metadata</h2>
+        <p>Status and scan details for the current merged log view.</p>
         <div class="metadata">
           <div class="meta-card">
             <span class="meta-label">Date</span>
             <span class="meta-value">{{log.date}}</span>
           </div>

           <div class="meta-card">
-            <span class="meta-label">File Index</span>
-            <span class="meta-value">{{log.file_index}}</span>
+            <span class="meta-label">Level</span>
+            <span class="meta-value">{{log.level}}</span>
           </div>

           <div class="meta-card">
-            <span class="meta-label">File Name</span>
-            <span class="meta-value">{{log.file_name}}</span>
+            <span class="meta-label">Keyword</span>
+            <span class="meta-value">{{log.keyword}}</span>
           </div>

           <div class="meta-card">
-            <span class="meta-label">Line Count</span>
+            <span class="meta-label">Matched Lines</span>
             <span class="meta-value">{{log.line_count}}</span>
           </div>
+
+          <div class="meta-card">
+            <span class="meta-label">Scanned Files</span>
+            <span class="meta-value">{{log.scanned_files}}</span>
+          </div>
+
+          <div class="meta-card">
+            <span class="meta-label">Scanned Lines</span>
+            <span class="meta-value">{{log.scanned_lines}}</span>
+          </div>
         </div>
         <div class="status">{{log.status_message}}</div>
       </section>
*** End Patch

